"""Capture committed UCI configuration with optional field encryption."""
from __future__ import annotations

import io
import json
import os
from pathlib import Path
import re
import shutil
import subprocess
import tarfile
import tempfile

from compiler import NAME, SECTION, CompileError, parse_uci, serialize_uci
from openwrt import DeployError, Transport
from rebuild import nix_string


class Expression(str):
    """An expression generated by this module, never raw device input."""


def nix_value(value, level=0):
    indent = "  " * level
    if isinstance(value, Expression):
        return "(" + str(value) + ")"
    if isinstance(value, str):
        return nix_string(value)
    if isinstance(value, dict):
        rows = [indent + "  " + nix_string(key) + " = " + nix_value(item, level + 1) + ";"
                for key, item in value.items()]
        return "{\n" + "\n".join(rows) + "\n" + indent + "}"
    if isinstance(value, list):
        return "[ " + " ".join(nix_value(item, level) for item in value) + " ]"
    if isinstance(value, bool):
        return "true" if value else "false"
    return json.dumps(value)


def read_snapshot(data, selected):
    if len(data) > 16 * 1024 * 1024:
        raise DeployError("configuration snapshot exceeds 16 MiB")
    packages, enabled, available = {}, set(), set()
    try:
        with tarfile.open(fileobj=io.BytesIO(data)) as archive:
            seen = set()
            for member in archive:
                name = member.name.removeprefix("./")
                if member.isdir():
                    continue
                if name in seen:
                    raise DeployError("duplicate snapshot entry")
                seen.add(name)
                parent, _, leaf = name.partition("/")
                if "/" in leaf or parent not in ("config", "init.d", "rc.d"):
                    raise DeployError("unexpected snapshot entry")
                if parent == "rc.d":
                    match = re.fullmatch(r"S[0-9]{2}([A-Za-z0-9_][A-Za-z0-9_.+-]*)", leaf)
                    if match:
                        enabled.add(match[1])
                elif parent == "init.d":
                    if NAME.fullmatch(leaf):
                        available.add(leaf)
                elif not member.isfile() or not NAME.fullmatch(leaf) or member.size > 1024 * 1024:
                    raise DeployError("unsupported UCI snapshot file")
                elif not selected or leaf in selected:
                    raw = archive.extractfile(member).read()
                    sections = parse_uci(raw)
                    serialize_uci(sections)  # Validate all identifiers and representable values.
                    packages[leaf] = sections
    except (tarfile.TarError, OSError, UnicodeError, CompileError):
        raise DeployError("snapshot contains invalid or unsupported UCI configuration") from None
    if not packages or set(selected) - set(packages):
        raise DeployError("selected UCI packages are absent or no configuration files were captured")
    return packages, available & enabled


def project_configuration(packages, enabled, args):
    encrypted, uci, selected = {}, {}, set(args.secret_option or [])
    matched = set()
    for package, sections in sorted(packages.items()):
        uci[package] = {}
        for name, spec in sections.items():
            options, private = {}, {}
            for option, value in spec["options"].items():
                field = ".".join((package, name, option))
                if field not in selected:
                    options[option] = value
                    continue
                matched.add(field)
                path = "/".join(("uci", package, name, option))
                if isinstance(value, list):
                    private[option] = {str(i): item for i, item in enumerate(value)}
                    options[option] = [Expression("secret " + nix_string(path + "/" + str(i)))
                                       for i in range(len(value))]
                else:
                    private[option] = value
                    options[option] = Expression("secret " + nix_string(path))
            if private:
                encrypted.setdefault(package, {})[name] = private
            uci[package][name] = {**spec, "options": options}
    if selected != matched:
        raise DeployError("a secret option selector does not match the snapshot")
    services = {}
    for service in sorted(enabled - {"wrtix-agent"}):
        candidates = {"network": ["network", "wireless"], "dnsmasq": ["dhcp"], "odhcpd": ["dhcp"]}
        triggers = [name for name in candidates.get(service, [service]) if name in packages]
        if triggers:
            services[service] = {"reloadOn": {"uci": triggers}}
    device = {"target_host": args.target_host, "ssh_port": args.port or 22,
              "uci": uci, "services": services}
    config = {"services": {"openwrt": {"enable": True, "devices": {args.device: device}}}}
    module = "# Review hardware settings and service reloads before first deployment.\n"
    if encrypted:
        module += "let\n  secret = key: { sops = { file = ./secrets.yaml; inherit key; }; };\nin\n"
    module += nix_value(config) + "\n"
    flake = '''{
  inputs.wrtix.url = INPUT;
  outputs = { wrtix, ... }: {
    openwrtConfigurations.imported = wrtix.lib.openwrtConfiguration {
      pkgs = wrtix.inputs.nixpkgs.legacyPackages.SYSTEM;
      modules = [ ./configuration.nix ];
    };
    apps.SYSTEM.default = wrtix.apps.SYSTEM.openwrt-rebuild;
  };
}
'''.replace("INPUT", nix_string(args.wrtix_input)).replace("SYSTEM", args.system)
    return module, flake, {"uci": encrypted} if encrypted else {}


def run(args, progress):
    if not SECTION.fullmatch(args.device) or len(args.device) > 64:
        raise DeployError("import requires a valid device name")
    destination = Path(args.output).absolute()
    if destination.exists() or destination.is_symlink():
        raise DeployError("import output already exists")
    if not destination.parent.is_dir():
        raise DeployError("import output parent directory does not exist")
    compiled = {"target_host": args.target_host, "ssh_port": args.port or 22}
    with Transport(args, {}, compiled, args.device) as transport:
        with progress.stage("Reading committed UCI configuration"):
            data = transport._run_stage("configuration capture", """set -eu
pending=$(uci changes)
test -z "$pending" || exit 43
tar -C /etc -cf - config init.d rc.d
pending=$(uci changes)
test -z "$pending" || exit 43
""")
    packages, enabled = read_snapshot(data, args.uci or [])
    module, flake, private = project_configuration(packages, enabled, args)
    if private:
        with progress.stage("Encrypting selected configuration fields"):
            try:
                encrypted = subprocess.run(["sops", "encrypt", "--input-type", "json", "--output-type", "yaml",
                                            "--age", ",".join(args.sops_age), "/dev/stdin"],
                                           input=json.dumps(private).encode(), stdout=subprocess.PIPE,
                                           stderr=subprocess.DEVNULL, timeout=120, check=False)
            except (OSError, subprocess.SubprocessError):
                raise DeployError("snapshot encryption failed") from None
            if encrypted.returncode or not encrypted.stdout:
                raise DeployError("snapshot encryption failed")
    # The project stays private while it is prepared. Publish its flake last.
    work = Path(tempfile.mkdtemp(prefix=".wrtix-import-", dir=destination.parent))
    try:
        (work / "configuration.nix").write_text(module)
        (work / "configuration.nix").chmod(0o600)
        (work / "flake.nix").write_text(flake)
        if private:
            (work / "secrets.yaml").write_bytes(encrypted.stdout)
        destination.mkdir(mode=0o700)  # Exclusive even if another importer raced us.
        try:
            # The flake is the last entry point published. Each file is complete.
            names = ["configuration.nix"] + (["secrets.yaml"] if private else []) + ["flake.nix"]
            for name in names:
                os.rename(work / name, destination / name)
        except BaseException:
            shutil.rmtree(destination)
            raise
    finally:
        if work.exists():
            shutil.rmtree(work)
    progress.message("Imported " + str(len(packages)) + " UCI packages into " + str(destination))
    print(json.dumps({"output": str(destination), "uci_packages": sorted(packages),
                      "review_required": True}))
